-- Учебные, полностью вымышленные сведения об автомобилях.
CREATE DATABASE IF NOT EXISTS vinscope_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vinscope_demo;

DROP TABLE IF EXISTS vehicles;
CREATE TABLE vehicles (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  vin CHAR(17) NOT NULL UNIQUE,
  brand VARCHAR(60) NOT NULL, model VARCHAR(80) NOT NULL, year SMALLINT UNSIGNED NOT NULL,
  engine VARCHAR(80) NOT NULL, transmission VARCHAR(60) NOT NULL, drive_type VARCHAR(40) NOT NULL, color VARCHAR(40) NOT NULL,
  risk_score TINYINT UNSIGNED NOT NULL DEFAULT 100, updated_at DATE NOT NULL,
  theft_status VARCHAR(60) NULL, theft_details VARCHAR(255) NULL,
  restrictions_status VARCHAR(60) NULL, restrictions_details VARCHAR(255) NULL,
  pledge_status VARCHAR(60) NULL, pledge_details VARCHAR(255) NULL,
  pts_status VARCHAR(80) NULL, pts_details VARCHAR(255) NULL,
  customs_status VARCHAR(80) NULL, customs_details VARCHAR(255) NULL,
  owners_count TINYINT UNSIGNED NULL, ownership_details VARCHAR(255) NULL,
  mileage_km INT UNSIGNED NULL, mileage_status VARCHAR(30) NULL, mileage_details VARCHAR(255) NULL,
  taxi_status VARCHAR(80) NULL, taxi_details VARCHAR(255) NULL,
  carsharing_status VARCHAR(80) NULL, carsharing_details VARCHAR(255) NULL,
  leasing_status VARCHAR(80) NULL, leasing_details VARCHAR(255) NULL,
  inspection_status VARCHAR(80) NULL, inspection_details VARCHAR(255) NULL,
  accident_status VARCHAR(80) NULL, accident_details VARCHAR(255) NULL,
  painting_status VARCHAR(80) NULL, painting_details VARCHAR(255) NULL,
  insurance_status VARCHAR(80) NULL, insurance_details VARCHAR(255) NULL,
  auction_status VARCHAR(80) NULL, auction_details VARCHAR(255) NULL,
  service_status VARCHAR(80) NULL, service_details VARCHAR(255) NULL
) ENGINE=InnoDB;

